import re
from docx import Document
from docx.shared import Pt, RGBColor, Inches, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.enum.section import WD_ORIENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

NAVY = RGBColor(0x1F,0x2A,0x44)
SEV_COLORS = {"Critical":"C00000","High":"E46C0A","Medium":"BF8F00","Low":"4F81BD","Aligned":"00804C","n/a":"7F7F7F"}

def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd"); shd.set(qn("w:val"),"clear"); shd.set(qn("w:color"),"auto"); shd.set(qn("w:fill"),hexcolor)
    tcPr.append(shd)

def add_runs(p, text, size=None, color=None, italic=False, bold_all=False):
    parts = re.split(r"(\*\*.+?\*\*)", text)
    for part in parts:
        if not part: continue
        if part.startswith("**") and part.endswith("**"):
            r = p.add_run(part[2:-2]); r.bold = True
        else:
            r = p.add_run(part); r.bold = bold_all or None
        if size: r.font.size = Pt(size)
        if color: r.font.color.rgb = color
        if italic: r.italic = True
    return p

class Doc:
    def __init__(self):
        d = Document()
        st = d.styles["Normal"]; st.font.name = "Calibri"; st.font.size = Pt(10.5)
        st.element.rPr.rFonts.set(qn("w:eastAsia"), "Calibri")
        st.paragraph_format.space_after = Pt(6); st.paragraph_format.line_spacing = 1.08
        for lvl, sz in ((1,15),(2,12.5),(3,11)):
            hs = d.styles["Heading %d" % lvl]; hs.font.name = "Calibri"; hs.font.size = Pt(sz); hs.font.color.rgb = NAVY; hs.font.bold = True
            hs.element.rPr.rFonts.set(qn("w:asciiTheme"), "") if False else None
            hs.paragraph_format.space_before = Pt(12 if lvl==1 else 9); hs.paragraph_format.space_after = Pt(4)
            hs.paragraph_format.keep_with_next = True
        sec = d.sections[0]
        sec.page_width = Inches(8.5); sec.page_height = Inches(11)
        sec.left_margin = sec.right_margin = Inches(0.9); sec.top_margin = sec.bottom_margin = Inches(0.85)
        hp = sec.header.paragraphs[0]; hp.alignment = WD_ALIGN_PARAGRAPH.CENTER
        add_runs(hp, "PRIVILEGED & CONFIDENTIAL | ATTORNEY-CLIENT COMMUNICATION | ATTORNEY WORK PRODUCT | DRAFT FOR BOARD REVIEW", size=7.5, color=RGBColor(0x80,0,0))
        fp = sec.footer.paragraphs[0]; fp.alignment = WD_ALIGN_PARAGRAPH.CENTER
        add_runs(fp, "Verdant Health Systems, Inc. | Bylaws vs. NCGC Guidelines Deviation Report | Page ", size=8)
        self._field(fp, "PAGE")
        self.d = d
    def _field(self, p, code):
        r = p.add_run(); r.font.size = Pt(8)
        f1 = OxmlElement("w:fldChar"); f1.set(qn("w:fldCharType"),"begin")
        it = OxmlElement("w:instrText"); it.set(qn("xml:space"),"preserve"); it.text = code
        f2 = OxmlElement("w:fldChar"); f2.set(qn("w:fldCharType"),"end")
        r._r.append(f1); r._r.append(it); r._r.append(f2)
    def h(self, lvl, text): return self.d.add_heading(text, level=lvl)
    def p(self, text, size=None, italic=False, align=None, after=None, indent=None):
        p = self.d.add_paragraph(); add_runs(p, text, size=size, italic=italic)
        if align=="center": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        if after is not None: p.paragraph_format.space_after = Pt(after)
        if indent: p.paragraph_format.left_indent = Inches(indent)
        return p
    def bullets(self, items, style="List Bullet"):
        for it in items:
            p = self.d.add_paragraph(style=style); add_runs(p, it); p.paragraph_format.space_after = Pt(3)
    def numbered(self, items): self.bullets(items, "List Number")
    def table(self, headers, rows, widths, size=8.5, header_fill="1F2A44", sev_col=None, zebra=True):
        t = self.d.add_table(rows=1, cols=len(headers)); t.style = "Table Grid"; t.alignment = WD_TABLE_ALIGNMENT.CENTER
        t.autofit = False
        for i,h in enumerate(headers):
            c = t.rows[0].cells[i]; c.text = ""; add_runs(c.paragraphs[0], h, size=size, color=RGBColor(0xFF,0xFF,0xFF), bold_all=True); shade(c, header_fill)
        # repeat header
        trPr = t.rows[0]._tr.get_or_add_trPr(); th = OxmlElement("w:tblHeader"); th.set(qn("w:val"),"true"); trPr.append(th)
        for ri,row in enumerate(rows):
            cells = t.add_row().cells
            for i,val in enumerate(row):
                c = cells[i]; c.text = ""
                lines = str(val).split("\n")
                for li,line in enumerate(lines):
                    para = c.paragraphs[0] if li==0 else c.add_paragraph()
                    para.paragraph_format.space_after = Pt(1)
                    add_runs(para, line, size=size)
                if sev_col is not None and i==sev_col:
                    key = str(val).split()[0].strip("*") if str(val) else ""
                    for k,v in SEV_COLORS.items():
                        if str(val).startswith(k) or str(val).startswith("**"+k):
                            for r in c.paragraphs[0].runs: r.font.color.rgb = RGBColor.from_string(v); r.bold = True
                            break
                elif zebra and ri%2==1: shade(c, "F2F4F8")
        for row in t.rows:
            for i,w in enumerate(widths):
                row.cells[i].width = Inches(w)
        # tblGrid widths
        grid = t._tbl.tblGrid
        for i,gc in enumerate(grid.findall(qn("w:gridCol"))):
            gc.set(qn("w:w"), str(int(widths[i]*1440)))
        self.d.add_paragraph().paragraph_format.space_after = Pt(2)
        return t
    def callout(self, title, text, fill="FFF4E5"):
        t = self.d.add_table(rows=1, cols=1); t.style = "Table Grid"; c = t.rows[0].cells[0]; shade(c, fill)
        c.text = ""; add_runs(c.paragraphs[0], "**"+title+"**", size=9.5)
        for line in text.split("\n"):
            pp = c.add_paragraph(); add_runs(pp, line, size=9.5); pp.paragraph_format.space_after = Pt(2)
        c.width = Inches(6.7)
        self.d.add_paragraph().paragraph_format.space_after = Pt(2)
    def pagebreak(self): self.d.add_page_break()
    def save(self, path): self.d.save(path)
